import {
    Table,
    BooleanColumn,
    ChoiceColumn,
    ConditionsColumn,
    StringColumn,
    TableNameColumn,
    FieldNameColumn,
} from '../../db'

export const sys_security_attribute = Table({
    name: 'sys_security_attribute',
    extends: 'sys_metadata',
    schema: {
        active: BooleanColumn({ default: true }),
        condition: ConditionsColumn({}),
        description: StringColumn({}),
        is_dynamic: BooleanColumn({ default: true }),
        is_localized: BooleanColumn({ default: false }),
        is_system: BooleanColumn({ default: false }),
        label: StringColumn({ mandatory: true }),
        lookup_table: TableNameColumn({}),
        lookup_table_column: FieldNameColumn({}),
        type: ChoiceColumn({
            default: 'string',
            choices: {
                integer: { label: 'integer' },
                string: { label: 'string' },
                compound: { label: 'compound' },
                boolean: { label: 'true | false' },
            },
        }),
    },
})
